{"filePath": "/Users/dwahl/Scripts/pantoken/docs/scripts/translate-home.ts", "content": "/**
 * Translate the home page (`docs/index.md`'s hero + features frontmatter) into every non-root
 * locale, mirroring `translate-guides.ts`/`translate-chrome.ts` for prose.
 *
 * The home page is VitePress `layout: home` frontmatter, not markdown prose, so it can't go through
 * `translate-guides.ts`'s whole-file `kind: "markdown"` unit (that would ship the YAML structure to
 * the adapter to reproduce verbatim, which is exactly the kind of fidelity risk `segment-markdown.ts`
 * exists to avoid). Instead this walks the source line-by-line: `text:`/`tagline:`/`title:`/`details:`
 * values are content-addressed `kind: "text"` units (same convention as sidebar labels and UI chrome),
 * and `link:` values are rewritten with the locale's route prefix (`/guide/…` → `LOCALES[locale]
 * .guidePrefix…`, `/api…` → `.apiPrefix…`) rather than translated. Every other line (the `pantoken`
 * brand name, `theme:`, `icon:` paths) passes through verbatim.
 *
 * Without this page, a locale with no hand-authored `<locale>/index.md` 404s at its route root —
 * VitePress has no built-in "fall back to English" for a missing locale route, it just doesn't have
 * a page to render. Run with `DOCS_TRANSLATION_ADAPTER=ai` for real translations; the default
 * `glossary` adapter is a keyless, deterministic fallback that at least renders a real page.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { LOCALES, NON_ROOT_LOCALES } from "../.vitepress/i18n.ts";
import { createTranslationAdapter } from "./api-translation.ts";
import { TranslationMemory, keyFor, translateUnits } from "./translation-memory.ts";

const docsRoot = join(import.meta.dirname, "..");
const source = readFileSync(join(docsRoot, "index.md"), "utf8");
const lines = source.split("\n");

const textLineRe = /^(\s*)(text|tagline|title|details):\s(.*)$/;
const linkLineRe = /^(\s*)(link):\s(.*)$/;

/** Double-quote a translated value so embedded colons/quotes can't break the YAML line. */
const quoteYaml = (value: string): string =>
  `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;

/** Rewrite a root-relative hero-action link (`/guide/…`, `/api`, `/api/…`) with the locale's prefix. */
const localizeLink = (link: string, locale: string): string => {
  const { guidePrefix, apiPrefix } = LOCALES[locale];
  if (link === "/api") return apiPrefix.replace(/\/$/, "");
  if (link.startsWith("/api/")) return apiPrefix + link.slice("/api/".length);
  if (link.startsWith("/guide/")) return guidePrefix + link.slice("/guide/".length);
  return link;
};

const sourceStrings = lines
  .map((line) => textLineRe.exec(line)?.[3])
  .filter((value) => value !== undefined);

for (const locale of NON_ROOT_LOCALES) {
  const adapter = createTranslationAdapter(locale);
  const memory = TranslationMemory.load(locale, "home");

  const translations = await translateUnits(
    adapter,
    memory,
    sourceStrings.map((text) => ({ kind: "text", source: text })),
  );

  const outLines = lines.map((line) => {
    const linkMatch = linkLineRe.exec(line);
    if (linkMatch) {
      const [, indent, key, value] = linkMatch;
      return `${indent}${key}: ${localizeLink(value, locale)}`;
    }
    const textMatch = textLineRe.exec(line);
    if (!textMatch) return line;
    const [, indent, key, value] = textMatch;
    const translated = translations.get(keyFor("text", value)) ?? value;
    return `${indent}${key}: ${quoteYaml(translated)}`;
  });

  const outDir = join(docsRoot, locale);
  mkdirSync(outDir, { recursive: true });
  writeFileSync(join(outDir, "index.md"), `${outLines.join("\n").trimEnd()}\n`);

  memory.save();
  console.log(
    `✓ localized home page for '${locale}' via '${adapter.name}' ` +
      `(${memory.misses} translated, ${memory.hits} cached)`,
  );
}
"}

